head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > hideSortIconOnNoData]<br/>GridView 에 데이터가 로드되지 않았을때 Header Column 의 정렬 상태 아이콘을 숨길지 설정합니다.",
    "validation" : [
        "sortable=true 이고 accessibility, sortHeaderDiv, showSortableImage 속성 중 하나 이상 true 일때 동작합니다.",
        "true 설정 시 GridView 에 표시된 데이터가 없을때 Header Column 에 정렬 상태 아이콘을 표시하지 않습니다.",
        "true 설정 시 GridView 에 데이터가 표시되면 정렬 상태 아이콘이 표시됩니다.",
        "true 설정 시 필터에 의해 데이터가 표시되지 않는 경우에도 적용됩니다.",
        "false(기본값) 설정 시 GridView 의 데이터 표시 여부와 관계없이 정렬 상태 아이콘을 항상 표시합니다.",
        "Header Column 의 개별 sortable 설정 시 GridView 의 sortable 이 무시되고, 미설정 시 GridView 의 sortable 이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_hideSortIconOnNoData : 공통 gdl_boolean 바인딩 (getText() 로 '' 미설정 / 'true' / 'false' 판단)
    //  - '' : 속성 자체를 추가하지 않음(기본 false) → 데이터 0건이어도 정렬 아이콘 항상 표시
    let vHide = con_hideSortIconOnNoData.getText();

    // 컬럼 구성/사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  전제(동작 조건) : sortable=true + showSortableImage=true (정렬 아이콘이 보이도록)
    //  [데이터 비우기] 로 0건 만들면 hideSortIconOnNoData=true 일때 정렬 아이콘이 숨겨지고,
    //  [데이터 채우기] 로 다시 데이터를 표시하면 아이콘이 표시됩니다. [필터로 데이터 숨기기] 도 동일하게 적용됩니다.
    //  false(기본) 일때는 데이터 0건이어도 아이콘이 항상 표시됩니다. col2(개별 sortable=false)는 정렬 아이콘이 없습니다.
    $c.gcm.createLabel('label="전제 : sortable=true, showSortableImage=true. con_hideSortIconOnNoData = ' + (vHide === '' ? '미설정(기본 false)' : vHide) + '. true 면 데이터 0건(데이터 비우기/필터로 숨기기)일때 정렬 아이콘 숨김, false 면 항상 표시."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (col1=text, col2=number, col3=text, col4=number)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="number"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 초기엔 데이터 4행이 로드된 상태 (정렬 아이콘 표시 상태에서 시작)
    let jsonData = [
        { "col1": "C", "col2": 200, "col3": "Cc", "col4": 30 },
        { "col1": "A", "col2": 400, "col3": "Aa", "col4": 10 },
        { "col1": "D", "col2": 100, "col3": "Dd", "col4": 40 },
        { "col1": "B", "col2": 300, "col3": "Bb", "col4": 20 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (createCList 공통 함수)
    //  - sortable="true"           : 동작 전제 (개별 미설정 Header col3,col4 에 GridView sortable 적용)
    //  - showSortableImage="true"  : 동작 전제 (정렬 아이콘이 항상 표시되도록)
    //  - hideSortIconOnNoData      : con 선택값 ('' 미설정이면 속성 미부여 → 기본 false)
    let properties = {
        dataList: "data:dlt_bind",
        sortable: true,
        showSortableImage: true,
    };
    if (vHide === 'true') {
        properties.hideSortIconOnNoData = true;
    } else if (vHide === 'false') {
        properties.hideSortIconOnNoData = false;
    }
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    // target 생성 (Body 4컬럼, 단일 Row 헤더)
    //  개별 sortable : hcol1=true(GridView 무시X) / hcol2=false(GridView true 무시 → 아이콘 없음) / hcol3,hcol4=미설정(GridView true 적용)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' sortEvent="onclick" id="" style="width:700px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="hideSortIconOnNoData 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    // col1 : 개별 sortable=true (GridView sortable 무시X, 정렬 아이콘 표시)
    strTarget += '<w2:column width="160" style="" inputType="text" sortable="true" id="hcol1" value="col1(개별true)"></w2:column>';
    // col2 : 개별 sortable=false (GridView true 무시 → 정렬 아이콘 없음)
    strTarget += '<w2:column width="160" style="" inputType="text" sortable="false" id="hcol2" value="col2(개별false)"></w2:column>';
    // col3 : 개별 미설정 (GridView true 적용)
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol3" value="col3(GridView)"></w2:column>';
    // col4 : 개별 미설정 (GridView true 적용)
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol4" value="col4(GridView)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" dataType="number" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" dataType="number" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 정렬 상태 아이콘 표시 여부 판정 (표시 시 .w2grid_head_sort_div_main 에 정렬상태 클래스(none/asc/desc) 부착, 숨김 시 base 만)
scwin.getSortIconShown = function () {
    let divs = Array.prototype.slice.call(document.querySelectorAll("[id*='target1_head'] .w2grid_head_sort_div_main"));
    let shown = divs.filter(function (d) { return /w2grid_head_sort_(none|asc|desc)/.test(d.className); });
    return { shownCount: shown.length, total: divs.length };
};

// 토글 채우기용 기본 4행 데이터 (comp_init 의 jsonData 와 동일)
scwin.jsonData = [
    { "col1": "C", "col2": 200, "col3": "Cc", "col4": 30 },
    { "col1": "A", "col2": 400, "col3": "Aa", "col4": 10 },
    { "col1": "D", "col2": 100, "col3": "Dd", "col4": 40 },
    { "col1": "B", "col2": 300, "col3": "Bb", "col4": 20 }
];

// 필터 적용 여부 추적 플래그
scwin.filterApplied = false;



// 데이터 비우기/채우기 토글 : 현재 데이터 건수로 판단하여 0건 ↔ 4건 토글
//  - 0건으로 : dlt_bind.setJSON([], false)  → hideSortIconOnNoData=true 면 정렬 아이콘 숨김 / false 면 유지
//  - 4건으로 : dlt_bind.setJSON(scwin.jsonData, false) → 데이터 표시 → 정렬 아이콘 다시 표시
scwin.btn_toggleData_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    if (dlt_bind.getRowCount() > 0) {
        dlt_bind.setJSON([], false);
        bottom.setReturnValue("[데이터] 비우기 → " + dlt_bind.getRowCount() + "건");
    } else {
        dlt_bind.setJSON(scwin.jsonData, false);
        bottom.setReturnValue("[데이터] 채우기 → " + dlt_bind.getRowCount() + "건");
    }
    bottom.setReturnValue("정렬 상태 아이콘 : " + (scwin.getSortIconShown().shownCount > 0 ? "표시됨" : "숨김") + " (데이터 " + target1.getDataLength() + "건)");
}



// 필터 적용/해제 토글 : scwin.filterApplied 플래그로 판단하여 필터(표시 0건) ↔ 해제 토글
//  - 적용 : dlt_bind.setFilter(type:'row', exactMatch:true, col1=ZZZ) → GridView.getDataLength() 0 (MCP 실측)
//  - 해제 : dlt_bind.clearFilter() → 데이터 다시 표시 (MCP 실측)
//  - hideSortIconOnNoData=true 면 필터로 0건일때도 정렬 아이콘 숨김 적용
scwin.btn_toggleFilter_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    if (!scwin.filterApplied) {
        dlt_bind.setFilter({ type: 'row', colIndex: 'col1', key: 'ZZZ', condition: 'and', exactMatch: true });
        scwin.filterApplied = true;
        bottom.setReturnValue("[필터] 적용 → 표시 " + target1.getDataLength() + "건");
    } else {
        dlt_bind.clearFilter();
        scwin.filterApplied = false;
        bottom.setReturnValue("[필터] 해제 → 표시 " + target1.getDataLength() + "건");
    }
    bottom.setReturnValue("정렬 상태 아이콘 : " + (scwin.getSortIconShown().shownCount > 0 ? "표시됨" : "숨김") + " (데이터 " + target1.getDataLength() + "건)");
}
